function svg(w,h,body,title){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)}"><style>text{font-family:Arial,sans-serif;font-size:11px;fill:#55716c}.strong-label{fill:#0d4242;font-weight:600}.axis-title{font-size:11px;fill:#55716c}.gridline{stroke:#e5eaf1;stroke-width:1}</style>${body}</svg>`;}
