function sectionShareURL(){
 const url=new URL(location.href);
 url.hash='';url.searchParams.set('view',state.view);
 for(const key of ['experiment','replicate','condition','response','referencePlate','cmax','ec50','includeReference'])url.searchParams.delete(key);
 if(!['dataSources','dataExport','batchComparison','assayEvidence','crosslinking'].includes(state.view)){
  url.searchParams.set('experiment',state.study);
  url.searchParams.set('replicate',String(state.study==='EXP26007301'?state.selectivityReplicate:state.study==='EXP26007104'?state.orientationReplicate:state.d1Replicate));
  if(state.study==='EXP26003438')url.searchParams.set('condition',state.d1Condition);
  if(state.study==='EXP26007104')url.searchParams.set('response',state.orientationMode);
  if(state.study==='EXP26007301')url.searchParams.set('referencePlate',String(state.selectivityReferencePlate));
  url.searchParams.set('cmax',String(state.threshold));url.searchParams.set('ec50',state.ec50Range);
  url.searchParams.set('includeReference',String(state.includeReference));
 }
 return url;
}
function syncSectionURL(){
 if(!atlasNavigationReady)return;
 const link=sectionShareURL();
 if(link.href!==location.href)history.replaceState(null,'',link.href);
 const message=$('atlasShareStatus');if(message)message.textContent='';
}
async function copySectionLink(){
 const output=$('atlasShareStatus');
 if(state.localAnalysis){output.textContent='This analysis uses files in your browser. Export its results to share them; a link cannot include local uploaded data.';return;}
 if(state.busy||!state.data){output.textContent='Wait for the selected Benchling ID to finish loading, then copy its link.';return;}
 const link=sectionShareURL().href;
 try{await navigator.clipboard.writeText(link);output.textContent='Section link copied. Individual compound choices and table filters are not included; use Excel to share your exact selection.';}
 catch(error){output.textContent='Copy this section link: '+link+' — table filters and individual compound choices are not included.';}
}
