 $('compareD1Campaign').textContent=open?'Show original compound list':'Compare with Cyclin D1/CypA';$('compareD1Campaign').setAttribute('aria-expanded',String(!!open));
 $('campaignComparison').hidden=!open;$('overviewListTable').hidden=!!open;$('exportOverviewList').hidden=!!open;
