 const data=state.data,rows=overviewListMembers(),context=overviewBasisContext('gds');
 campaignLeftContext={benchling_id:context.experiment,biological_replicate:context.replicate,run_date:context.date,condition:context.condition,response_source:context.response,ec50_band:AtlasPotency.labels[s.band],cmax_cutoff:state.threshold};
