  $('campaignComparisonCount').textContent=`${matched} of ${rows.length} visible compound batches have an exact D1 match. ${rows.length-matched} have no exact batch match; missing values remain unavailable.`;
  $('campaignComparisonTable').innerHTML=rows.length?AtlasCampaignComparison.table(campaignVisibleRows,s.target+' · GDS · Replicate '+context.replicate,'Cyclin D1/CypA · GDS · Replicate unassigned'):'<p>No compounds match the current list and search.</p>';
  $('exportCampaignComparison').disabled=!rows.length;
