function renderFingerprint(){const qs=curvesFor(state.mapCompound),w=measure('fingerprint'),h=Math.max(210,qs.length*46+60),left=87,right=45,top=15,max=Math.max(state.threshold+20,...qs.map(q=>q.cmax)),min=Math.min(0,...qs.map(q=>q.cmax)),x=linear([min,max],[left,w-right]);let b='';for(const tick of ticks([min,max],4)){b+=line(x(tick),top,x(tick),h-42);b+=txt(x(tick),h-25,fmt(tick,0),'text-anchor="middle"');}qs.forEach((q,i)=>{const y=top+i*46;b+=txt(left-9,y+20,q.target,'text-anchor="end"');b+=`<rect x="${Math.min(x(0),x(q.cmax))}" y="${y+6}" width="${Math.abs(x(q.cmax)-x(0))}" height="22" rx="3" fill="${color(q.target)}" opacity="${active(q)?1:.4}" ${tip(`${q.target}: ${fmt(q.cmax,3)}; ${activityStatus(q)}`)}/>`;b+=txt(x(q.cmax)+6,y+21,fmt(q.cmax,1),'class="strong-label"');});b+=line(x(state.threshold),top,x(state.threshold),h-42,'#96a4b6','stroke-dasharray="3 3"');b+=txt((left+w-right)/2,h-5,'Cmax (corrected response units)','text-anchor="middle" class="axis-title"');$('fingerprint').innerHTML=svg(w,h,b,`${compoundLabel(state.mapCompound)}: Cmax fingerprint by target`);}
function rank(values){const ids=values.map((v,i)=>({v,i})).sort((a,b)=>a.v-b.v),out=[];for(let i=0;i<ids.length;){let j=i;while(j+1<ids.length&&ids[j+1].v===ids[i].v)j++;for(let k=i;k<=j;k++)out[ids[k].i]=(i+j)/2+1;i=j+1;}return out;}
function spearman(a,b){if(a.length<3)return null;const x=rank(a),y=rank(b),xm=x.reduce((a,b)=>a+b,0)/x.length,ym=y.reduce((a,b)=>a+b,0)/y.length;let s=0,sx=0,sy=0;for(let i=0;i<x.length;i++){s+=(x[i]-xm)*(y[i]-ym);sx+=(x[i]-xm)**2;sy+=(y[i]-ym)**2;}return sx&&sy?s/Math.sqrt(sx*sy):null;}
function renderCorrelation(){const d=state.data;let b='<table class="correlation-table"><thead><tr><th>'+(state.study==='EXP26007104'?'Configuration':'Target')+'</th>'+d.targets.map(t=>`<th style="text-align:center">${esc(t)}</th>`).join('')+'</tr></thead><tbody>';for(const t of d.targets){b+=`<tr><th>${esc(t)}</th>`;for(const u of d.targets){const pairs=d.compounds.map(c=>{const qs=curvesFor(c);return [qs.find(q=>q.target===t),qs.find(q=>q.target===u)];}).filter(p=>p[0]&&p[1]),r=spearman(pairs.map(p=>p[0].cmax),pairs.map(p=>p[1].cmax));const hue=r==null?'#f4f6f9':r>=0?`rgba(36,101,203,${Math.abs(r)*.23})`:`rgba(205,125,55,${Math.abs(r)*.23})`;b+=`<td style="background:${hue}">${r==null?'—':fmt(r,2)}<small>n = ${pairs.length}</small></td>`;}b+='</tr>';}b+='</tbody></table>';$('correlation').innerHTML=b;}
function renderResults(){const mode=$('sourceMode').value,term=$('search').value.trim().toLowerCase(),target=$('targetFilter').value,only=$('activeOnly').checked;const qs=state.data.curves.filter(q=>(!mode||q.report?.source_mode===mode)&&(!term||q.compound.toLowerCase().includes(term))&&(!target||q.target===target)&&ec50Matches(q)&&(!only||active(q)));$('resultCount').textContent=`${qs.length} compound–${state.study==='EXP26007104'?'configuration':'target'} rows · ${qs.filter(active).length} meet ${activityRule()}. All-parameter CSV contains every pair; active CSV uses the selected Cmax and EC50 criteria. Export displayed table CSV follows these filters. All-parameter CSV includes every pair in the selected run; active CSV uses the selected activity criteria.`;let b='<table><thead><tr>'+['Compound','Batch','Role',state.study==='EXP26007104'?'Configuration':'Target','Source classification','Activity','Cmax','Cmax basis','Reported EC50 (µM)','Reported EC50 range','Refit EC50 (µM)','Hill','S0','Sinf','Amplitude','Refit R²','RMSE','Source Valid','Source R²','Source QC','Refit limitations'].map(h=>`<th>${h}</th>`).join('')+'</tr></thead><tbody>';for(const q of qs){const f=q.fit||{},r=q.report||{};b+=`<tr><td><button class="compound-link" data-compound="${esc(q.compound)}" data-target="${esc(q.target)}">${esc(compoundBase(q.compound))}</button></td><td>${esc(compoundBatch(q.compound))}</td><td>${q.is_reference?'Positive reference':'Library compound'}</td><td>${esc(q.target)}</td><td>${esc(r.source_mode||'Not reported')}</td><td><span class="pill ${active(q)?'':'neutral'}">${esc(activityStatus(q))}</span></td><td class="num">${fmt(q.cmax,2)}</td><td>${esc(q.cmax_basis)}</td><td class="num">${esc(ecText(q).replace(' µM',''))}</td><td>${esc(ecRangeLabel(q))}</td><td class="num">${sig(f.ec50)}</td><td class="num">${fmt(f.hill)}</td><td class="num">${fmt(f.s0)}</td><td class="num">${fmt(f.sinf)}</td><td class="num">${fmt(f.amplitude)}</td><td class="num">${fmt(f.r2,3)}</td><td class="num">${fmt(f.rmse)}</td><td>${esc(r.source_valid||'not reported')}</td><td class="num">${fmt(r.source_r2,3)}</td><td class="qc-cell">${esc(r.source_qc||'none')}</td><td class="qc-cell">${esc(q.fit_flags.join('; ')||'Within range; inspect source QC')}</td></tr>`;}b+='</tbody></table>';$('resultsTable').innerHTML=b;}
function renderMethods(){const d=state.data;if(!d)return;$('experimentDetails').innerHTML=`<p><strong>${d.compounds.length} compounds · ${d.targets.length} ${state.study==='EXP26007104'?'configurations':'targets'}</strong><br>${d.curves.length} curves · ${fmt(d.wells_total,0)} sample wells<br>${d.wells_excluded} masked/ignored wells excluded</p><h3>Cmax definitions</h3><p>${d.cmax_bases.map(esc).join('<br>')}</p><h3>Source files</h3><p style="overflow-wrap:anywhere">${d.files.map(esc).join('<br><br>')}</p>${d.notes.length?'<h3>Data notes</h3><p>'+d.notes.map(esc).join('<br>')+'</p>':''}`;}
