async function selectivityRun(rep){
 if(!state.selectivityRuns[rep]){
  const r=await fetch(rep===2?'./selectivity-rep2.json?v=rep2-gds-parameters-1':'./sample.json?v=plate-assignments-1');
  if(!r.ok)throw new Error('Biological replicate '+rep+' could not be loaded.');
  const data=await r.json();data.biological_replicate=rep;data.run_date=rep===2?'2026-10-15':'2026-10-09';data.experiment='EXP26007301';state.selectivityRuns[rep]=data;
 }
 const viewKey=rep+'-'+state.selectivityReferencePlate;
 if(!state.selectivityPrepared[viewKey]){
  const prepared=AtlasSelectivityIdentity.prepare(state.selectivityRuns[rep],{referencePlate:String(state.selectivityReferencePlate)});
  const [pca,cluster]=AtlasCore.maps(prepared.curves,prepared.targets,prepared.compounds);
  prepared.pca=pca;prepared.cluster_order=cluster;
  prepared.notes.push('The compound map is recalculated from the selected reference plate, using the same supplied Cmax values. Reference plates are not pooled.');
  state.selectivityPrepared[viewKey]=prepared;
 }
 return state.selectivityPrepared[viewKey];
}
async function d1Run(rep,condition){
 const key=rep+condition;
 if(!state.d1Runs[key]){
  const url=key==='1B'?'./cyclind1.json?v=d1-local-1':`./cyclind1-bio${rep}-${condition}.json?v=d1-two-replicates-2`;
  const r=await fetch(url);if(!r.ok)throw new Error('Cyclin D1 biological replicate could not be loaded.');
  const data=await r.json();Object.assign(data,{experiment:'EXP26003438',biological_replicate:rep,run_date:rep===1?'2026-09-02':'2026-09-03',source_folder:rep===1?'20260902':'20260904',condition_code:condition,condition_label:condition==='A'?'No CypA inhibitor':'+25 µM CypA inhibitor'});
  state.d1Runs[key]=data;
 }
 return state.d1Runs[key];
}
async function sample(){if(state.busy)return;state.uploadedSelectivity=null;busy(true);status('Loading selected Benchling ID…');try{
 const study=$('studySelect').value;
 let data;if(study==='EXP26007104')data=await orientationRun(state.orientationReplicate,state.orientationMode);else if(study==='EXP26007301')data=await selectivityRun(state.selectivityReplicate);else data=await d1Run(state.d1Replicate,state.d1Condition);
 const previousCompound=state.study===study?state.compound:undefined;await setStudyProfile(study);state.localAnalysis=false;load(data,previousCompound);status('');
}catch(e){status(e.message,true);}finally{busy(false);}}
async function renderBiologicalReplicates(){
 const host=$('biologicalReplicates');if(state.uploadedSelectivity){host.innerHTML='<section class="panel"><h2>Local uploaded analysis</h2><p>This uploaded run has no linked biological replicate. View or export its curves and parameters, or reload the selected Benchling ID to compare its supplied biological runs.</p></section>';return;}if(state.study==='EXP26007104'){const [a,b]=await Promise.all([orientationRun(1,state.orientationMode),orientationRun(2,state.orientationMode)]);if(state.study==='EXP26007104'&&state.view==='biologicalReplicates')AtlasSelectivityView.render({host,a,b,compound:state.compound,threshold:state.threshold,ec50Range:state.ec50Range,onCompound:c=>{state.compound=c;syncCompoundPicker('compound');renderBiologicalReplicates();}});return;}if(state.study==='EXP26003438'){await renderCypaDependency('biologicalReplicates');return;}
 host.innerHTML='<section class="panel">Loading biological replicates…</section>';
 try{const [a,b]=await Promise.all([selectivityRun(1),selectivityRun(2)]);if(state.study!=='EXP26007301'||state.view!=='biologicalReplicates')return;
  AtlasSelectivityView.render({host,a,b,compound:state.compound,threshold:state.threshold,ec50Range:state.ec50Range,onCompound:c=>{state.compound=c;syncCompoundPicker('compound');renderBiologicalReplicates();}});
 }catch(e){host.textContent=e.message;}
}
