document.addEventListener('pointermove',e=>{const node=e.target.closest('[data-tip]');if(!node){$('tooltip').hidden=true;return;}$('tooltip').hidden=false;$('tooltip').textContent=node.dataset.tip;const rect=$('tooltip').getBoundingClientRect();$('tooltip').style.left=Math.max(8,Math.min(innerWidth-rect.width-10,e.clientX+13))+'px';$('tooltip').style.top=Math.max(8,Math.min(innerHeight-rect.height-10,e.clientY+13))+'px';});
