async function setStudyProfile(study){state.study=study;$('orientationReplicateField').hidden=$('orientationModeField').hidden=study!=='EXP26007104';$('orientationReplicate').value=String(state.orientationReplicate);$('orientationMode').value=state.orientationMode;$('ec50Range').disabled=study==='EXP26007104'&&state.orientationMode==='ratio';document.querySelector('[data-view="configurationComparison"]').hidden=study!=='EXP26007104';$('selectivityReplicateField').hidden=$('selectivityReferencePlateField').hidden=study!=='EXP26007301';$('selectivityReferencePlate').value=String(state.selectivityReferencePlate);$('d1ReplicateField').hidden=$('d1ConditionField').hidden=study!=='EXP26003438';$('d1Replicate').value=String(state.d1Replicate);$('d1Condition').value=state.d1Condition;$('selectivityReplicate').value=String(state.selectivityReplicate);$('studySelect').value=study;profile={...studyDefaults[study]};try{Object.assign(profile,JSON.parse(localStorage.getItem('atlas-profile-'+study)||'{}'));}catch(e){}showProfile();}
function showProfile(){for(const [key,out,input] of [['title','experimentTitle','profileTitle'],['description','experimentDescription','profileDescription'],['id','experimentId','profileId']]){$(out).textContent=profile[key]||'Not entered';$(input).value=profile[key]||'';}$('profileBenchling').value=/^https?:/.test(profile.benchling||'')?profile.benchling:'';$('studyContext').textContent=studyDefaults[state.study]?.context||'';$('studyLinks').innerHTML=state.study==='EXP26003438'?`<a href="${esc(studyDefaults.EXP26003438.benchling)}" target="_blank" rel="noreferrer">Open Benchling</a> · <a href="https://revmed.benchling.com/revmed/f/lib_gdrBEMwl-cell-biology-screening/etr_g6PngiaFTF-screening-of-the-cypa-tci-library-in-cyclind1cypa-nanobret-at-pharmaron-primary-screening/edit" target="_blank" rel="noreferrer">Pharmaron primary screen</a>`:'';}
$('profileForm').addEventListener('submit',e=>{e.preventDefault();profile={title:$('profileTitle').value,description:$('profileDescription').value,id:$('profileId').value,benchling:$('profileBenchling').value};try{localStorage.setItem('atlas-profile-'+state.study,JSON.stringify(profile));status('Assay details saved in this browser.');}catch(e){status('Details updated for this session; browser storage is unavailable.');}showProfile();});
