const requestedCondition=new URLSearchParams(location.search).get('condition');if(requestedCondition==='A'||requestedCondition==='B')state.d1Condition=requestedCondition;
const requestedResponse=new URLSearchParams(location.search).get('response');if(requestedResponse==='ratio')state.orientationMode='ratio';
