async function renderCurveAssays(){
 const host=$('curveAssays'),potencyHost=$('curveSourcePotency'),compound=state.compound;
 host.innerHTML='';potencyHost.innerHTML='';
 if(state.study!=='EXP26003438')return;
 try{const data=await AtlasAssaysView.load();if(!state.sourceParameters){const r=await fetch('./cyclind1-source-parameters.json');if(!r.ok)throw new Error('Source parameter report unavailable.');state.sourceParameters=await r.json();}if(state.study==='EXP26003438'&&state.compound===compound){AtlasAssaysView.renderPotencySummary({host:potencyHost,data,compound,source:state.sourceParameters.find(q=>q.compound===compound)});AtlasAssaysView.renderCompound({host,data,compound});}}catch(e){host.textContent=e.message;}
}

async function orientationRun(rep,mode){
 const key=rep+'-'+mode;if(!state.orientationRuns[key]){const r=await fetch('./orientation-rep'+rep+'-'+mode+'.json?v=orientation-ratio-config-2');if(!r.ok)throw new Error('Orientation biological replicate '+rep+' could not be loaded.');state.orientationRuns[key]=await r.json();}return state.orientationRuns[key];
}
async function renderConfigurations(){
 const host=$('configurationComparison');if(state.study!=='EXP26007104'){host.innerHTML='<section class="panel">Select EXP26007104 to compare tag configurations.</section>';return;}
 const [a,b]=await Promise.all([orientationRun(1,state.orientationMode),orientationRun(2,state.orientationMode)]);
 if(state.study==='EXP26007104'&&state.view==='configurationComparison')AtlasOrientationView.compare({host,a,b,compound:state.compound,onCompound:c=>{state.compound=c;syncCompoundPicker('compound');renderConfigurations();}});
}
function updateDimensionLabels(){
 const orientation=state.study==='EXP26007104';
 let navNumber=0;document.querySelectorAll('nav [data-view]').forEach(el=>{if(!el.hidden)el.querySelector('span').textContent=String(++navNumber).padStart(2,'0');});
 $('rankingTitle').textContent=orientation?'Which configuration has the most hits?':'Which target has the most hits?';
 $('heatTitle').textContent=orientation?'Compound × configuration activity map':'Compound × target activity map';
 $('correlationTitle').textContent=orientation?'Configuration profile relationships':'Target profile relationships';
 $('fingerprintTitle').textContent=orientation?'Configuration response fingerprint':'Response fingerprint';
 $('mapProfileDescription').textContent='Point colors identify the highest-response '+(orientation?'configuration':'target')+'. This map describes assay profiles, not chemical structures or mechanisms.';
}
$('orientationReplicate').addEventListener('change',()=>{state.orientationReplicate=Number($('orientationReplicate').value);sample();});
$('orientationMode').addEventListener('change',()=>{state.orientationMode=$('orientationMode').value;if(state.orientationMode==='ratio'){state.ec50Range='all';$('ec50Range').value='all';}sample();});

async function renderCrosslinking(){
 const host=$('crosslinking');host.innerHTML='<section class="panel">Loading crosslinking evidence…</section>';
 try{const data=state.crosslinkData||await AtlasCrosslink.load();state.crosslinkData=data;if(state.view!=='crosslinking')return;
  $('datasetLabel').textContent=data.compounds.length+' crosslinking source IDs · '+data.contexts.length+' source contexts · paired No CypA / +CypA conditions';
  $('footerStats').textContent=data.records.length+' compound–context comparisons · '+data.summary.condition_records+' condition distributions';
  AtlasCrosslink.render({host,data,compound:state.crosslinkCompound||state.compound,onCompound:c=>{state.crosslinkCompound=c;}});
 }catch(e){if(state.view==='crosslinking')host.textContent=e.message;}
}
async function renderCurveCrosslink(){
 const host=$('curveCrosslink'),compound=state.compound,study=state.study;host.innerHTML='';
 try{const data=state.crosslinkData||await AtlasCrosslink.load();state.crosslinkData=data;if(state.view==='curves'&&state.compound===compound&&state.study===study)AtlasCrosslink.compact({host,data,compound});}catch(e){if(state.view==='curves'&&state.compound===compound)host.textContent=e.message;}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-crosslink-open]');if(b){state.crosslinkCompound=b.dataset.crosslinkOpen||null;setView('crosslinking');}});


// The data catalog spans published experiments, independently of the selected curve run.
let dataExportMounted=false;
function renderDataExport(){
 $('datasetLabel').textContent='All included assays · choose measurements, time points, batches and source details';
 $('footerStats').textContent='Source-linked data selection';
 if(dataExportMounted)return;
 dataExportMounted=true;
 AtlasDataExport.render({host:$('dataExport'),categories:AtlasDataCatalog.categories,columns:AtlasDataCatalog.columns,load:()=>AtlasDataCatalog.load({onProgress:progress=>{
  const message=$('dataExport').querySelector('[role="status"]');
  if(message)message.textContent='Loading data and sources: '+progress.file+' · '+progress.records.toLocaleString()+' measurements ready…';
 }})});
}
$('openDataExport').addEventListener('click',()=>setView('dataExport'));

function renderDataSources(){
 $('datasetLabel').textContent='Original supplied files, workbook sheets and source roles';
 $('footerStats').textContent='Trace results to the supplied files';
 AtlasSources.render({host:$('dataSources'),study:state.sourceGroup||state.study});
}
$('openDataSources').addEventListener('click',()=>{state.sourceGroup=null;setView('dataSources');});
document.addEventListener('click',event=>{const button=event.target.closest('button[data-source-group]');if(button){state.sourceGroup=button.dataset.sourceGroup;setView('dataSources');}});

function renderBatchComparison(){$('datasetLabel').textContent='All supplied Benchling IDs and assay sources · Compound Management batches kept separate';$('footerStats').textContent='Batch comparisons retain each source measurement';document.querySelector('.page-header .eyebrow').textContent='COMPOUND MANAGEMENT BATCHES';AtlasBatchComparison.render({host:$('batchComparison'),compound:state.batchCompound||state.compound,onCompound:id=>{state.batchCompound=id;}});}

$('compareCompoundGraphs').addEventListener('click',()=>setView('compoundGraphs'));
